    if gnd and (gnd - G.pos()).Magnitude > 0.5 then G.C.flying = false G.tp(gnd) task.wait(0.4) end
    local p = G.pos()
    local px, py, pz = math.floor(p.X), math.floor(p.Y), math.floor(p.Z)
    local tbl, placed
    for dx = -4, 4 do for dy = -2, 2 do for dz = -4, 4 do
        if not tbl and G.bname(G.get(px + dx, py + dy, pz + dz)) == "crafting_table" then tbl = { px + dx, py + dy, pz + dz } end
    end end end
    if not tbl then
        if CRAFT.count(function(n) return n == "crafting_table" end) == 0 and CRAFT.can("crafting_table", 2) then CRAFT.make("crafting_table") end
        local ti
        for i = 1, 36 do local s = G.CI.state.slots[i] if s and s.name == "crafting_table" then ti = i end end
        if not ti then say(__T["Need a crafting table"]) return false end
        for r = 1, 3 do for dx = -r, r do for dz = -r, r do for dy = -1, 1 do
            local x, y, z = px + dx, py + dy, pz + dz
            if not tbl and not (dx == 0 and dz == 0) and G.get(x, y, z) % 256 == 0 and G.solid(x, y - 1, z) then tbl = { x, y, z } end
        end end end end
        if not tbl then return false end
        local sel = G.CI.state.selected or 0
        if ti <= 9 then gcall(G.CI.select, ti - 1) else gcall(G.CI.swap, "inv", ti, sel) end
        task.wait(0.4)
        pcall(function() G.R.Place:InvokeServer(tbl[1], tbl[2], tbl[3], G.BL.id("crafting_table")) end)
        task.wait(0.4)
        placed = true
    end
    pcall(function() G.R.Use:InvokeServer(tbl[1], tbl[2], tbl[3]) end)
    local t0 = os.clock()
    repeat task.wait(0.1) until (G.CI.state.craftSize or 2) >= 3 or os.clock() - t0 > 2
    CRAFT.make(want)
    local okc, rc = pcall(function() return G.R.CloseScreen:InvokeServer() end)
    if okc and type(rc) == "table" then gcall(G.CI.apply, rc) end
    task.wait(0.3)
    if placed then G.brk(tbl[1], tbl[2], tbl[3]) task.wait(0.6) MINE.vacuum(5) end
    local ok = CRAFT.hasSword() and not (up and CRAFT.upgrade())
    if ok then S.crafted = (S.crafted or 0) + 1 say(__T["Crafted "] .. G.pretty(want)) end
    LOG("craft", want, ok)
    return ok
end
local JER = { last = 0 }
function JER.hungry(m)
    local h = Workspace:GetAttribute("JerryHunger")
    return m:GetAttribute("Hungry") == true or (typeof(h) == "number" and h < 1) or Workspace:GetAttribute("FoodStep") == "feed"
end
function JER.feed(m, canTp)
    if not G.holdFood() then return false, __T["No food in your bag"] end
    local mp = G.mpos(m)
    local back
    if (mp - G.pos()).Magnitude > 3.5 then
        if not canTp then return false, __T["Walk closer to feed"] end
        back = G.pos()
        local s = G.stand(Vector3.new(math.floor(mp.X), math.floor(mp.Y), math.floor(mp.Z)), 3) or (mp + Vector3.new(1.5, 0, 0))
        G.tp(s) task.wait(0.4)
    end
    local ok = pcall(function() G.R.Interact:InvokeServer(m) end)
    task.wait(0.5)
    if back then G.tp(back) end
    if ok then S.fed += 1 end
    return ok
end
