    CB:AddSlider("cb_range", { Text = __T["Farm Range"], Default = 160, Min = 32, Max = 400, Rounding = 0, Suffix = __T[" blocks"] })
    CB:AddToggle("cb_sword", { Text = __T["Auto Hold Weapon"], Default = true })
    CB:AddDropdown("cb_weapon", { Text = __T["Weapon"], Values = G.weapons(), Default = "Best Available", FormatDisplayValue = function(v) return v == "Best Available" and v or G.pretty(v) end })
    CB:AddToggle("cb_craft", { Text = __T["Auto Craft Sword"], Default = true, Tooltip = __T["Makes your picked sword when it breaks"] })
    CB:AddToggle("cb_jerry", { Text = __T["Fight Wild Jerry"], Default = false, Tooltip = __T["Survival: also attacks Jerry. Never your tame Jerry"] })
    UI.cb = CB:AddLabel("", true)
    local PV = Tab:AddRightGroupbox(__T["PVP"], "swords")
    local function pvpOn(v)
        if v and lp:GetAttribute("Pvp") ~= true then
            if S.pvpWas == nil then S.pvpWas = false end
            task.spawn(function() pcall(function() G.R.Pvp:InvokeServer(true) end) end)
        elseif not v and not on("pv_aura") and not on("pv_chase") and S.pvpWas == false then
            S.pvpWas = nil
            task.spawn(function() pcall(function() G.R.Pvp:InvokeServer(false) end) end)
        end
    end
    PV:AddToggle("pv_aura", { Text = __T["Player Kill Aura"], Default = false, Tooltip = __T["Hits PVP players in reach. Turns your PVP on"], Callback = pvpOn })
    PV:AddToggle("pv_chase", { Text = __T["Chase PVP Players"], Default = false, Tooltip = __T["Hovers over PVP players and attacks"], Callback = pvpOn })
    PV:AddToggle("pv_friends", { Text = __T["Skip Friends"], Default = true })
    PV:AddSlider("pv_range", { Text = __T["Chase Range"], Default = 120, Min = 16, Max = 600, Rounding = 0, Suffix = __T[" blocks"] })
    UI.pv = PV:AddLabel("", true)
    local FR = {}
    local function pvpTarget(r)
        local p0, best, bd = G.pos(), nil, nil
        for _, pl in ipairs(Players:GetPlayers()) do
            if pl ~= lp and pl:GetAttribute("Pvp") == true and (pl:GetAttribute("Health") or 1) > 0 then
                if FR[pl] == nil then FR[pl] = false task.spawn(function() local ok, f = pcall(function() return lp:IsFriendsWith(pl.UserId) end) FR[pl] = ok and f or false end) end
                local c = pl.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                if hrp and not (on("pv_friends") and FR[pl]) then
                    local d = ((hrp.Position - Vector3.new(0, 2.7, 0)) / G.BLOCK - p0).Magnitude
                    if d <= r and (not bd or d < bd) then best, bd = pl, d end
                end
            end
        end
        return best, bd
    end
    task.spawn(function()
        local hover = false
        while RUNNING do
            local ok, w = pcall(function()
                local chase = on("pv_chase") and not UI.busy
                if not (on("pv_aura") or chase) or not G.inWorld() or G.dead() then return 0.3 end
                if lp:GetAttribute("Pvp") ~= true then setText(UI.pv, __T["Your PVP is off"]) return 1 end
                local pl, d = pvpTarget(chase and val("pv_range", 120) or 5.2)
                if not pl then setText(UI.pv, __T["No PVP players in range"]) return 0.3 end
                local hrp = pl.Character.HumanoidRootPart
                if chase then
                    local want = (hrp.Position - Vector3.new(0, 2.7, 0)) / G.BLOCK + Vector3.new(0, 3, 0)
                    if (G.pos() - want).Magnitude > 1.5 then G.C.canFly = true G.C.flying = true hover = true G.tp(want) task.wait(0.1) end
                end
                if on("cb_sword") then G.holdWeapon() end
                local gap = 0.66 - (os.clock() - KILL.last)
                if gap > 0 then task.wait(gap) end
                KILL.last = os.clock()
                local h0 = pl:GetAttribute("Health")
                local okh, r = pcall(function() return G.R.Attack:InvokeServer(pl.Character, false) end)
                task.wait(0.12)
                LOG("pvp hit", pl.Name, h0, "->", pl:GetAttribute("Health"), r)
                setText(UI.pv, __T["Target: "] .. pl.DisplayName .. " · " .. tostring(pl:GetAttribute("Health") or "?") .. __T[" hp"])
                return 0.05
            end)
            if not ok then LOG("err pvp", w) w = 1 end
            if hover and not on("pv_chase") then hover = false if G.C and not G.needFly() then G.C.flying = false G.C.canFly = lp:GetAttribute("Creative") == true end end
            task.wait(w)
        end
    end)
    local function kinds()
        local seen, t = {}, {}
        for _, m in ipairs(G.mobs()) do local k = m:GetAttribute("Kind") if k and not seen[k] and k ~= "puppy" and k ~= "villager" and k ~= "arrow" then seen[k] = true t[#t + 1] = k end end
        for k, s in pairs(val("cb_kinds", {})) do if s and not seen[k] then seen[k] = true t[#t + 1] = k end end
        table.sort(t)
        return t
    end
    task.spawn(function()
        local last = ""
        while RUNNING do
            local t = kinds()
            local key = table.concat(t, ",")
            if key ~= last and key ~= "" then last = key pcall(function() Opt.cb_kinds:SetValues(t) end) end
            task.wait(5)
        end
    end)
    local folder = Instance.new("Folder")
    folder.Name = "CWD" .. tostring(math.random(1e6))
    pcall(function() folder.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
    if not folder.Parent then folder.Parent = lp:WaitForChild("PlayerGui") end
    onClean(function() pcall(function() folder:Destroy() end) end)
    local anchors = Instance.new("Folder")
    anchors.Name = "CWA" .. tostring(math.random(1e6))
    anchors.Parent = Workspace
    onClean(function() pcall(function() anchors:Destroy() end) end)
    local COL = { diamond_ore = Color3.fromRGB(80, 230, 255), gold_ore = Color3.fromRGB(255, 210, 60), iron_ore = Color3.fromRGB(220, 180, 150), coal_ore = Color3.fromRGB(120, 120, 120), redstone_ore = Color3.fromRGB(255, 60, 60), lapis_ore = Color3.fromRGB(70, 110, 255), emerald_ore = Color3.fromRGB(60, 230, 110) }
    local function tag(parent, text, color, size)
        local bb = Instance.new("BillboardGui")
        bb.AlwaysOnTop, bb.Size, bb.LightInfluence = true, UDim2.fromOffset(size or 110, 22), 0
        local tl = Instance.new("TextLabel")
        tl.BackgroundTransparency, tl.Size, tl.Font, tl.TextSize, tl.TextStrokeTransparency = 1, UDim2.fromScale(1, 1), Enum.Font.GothamBold, 14, 0.3
        tl.Text, tl.TextColor3 = text, color
        tl.Parent = bb
        bb.Parent = folder
        return bb, tl
    end
    local OE = { list = {}, pool = {} }
    local function clearOre() for _, e in ipairs(OE.pool) do e.bb.Enabled = false end end
    task.spawn(function()
        while RUNNING do
            if on("wd_esp") and G.inWorld() then
                local want, n = MINE.want()
                local key = n .. ":" .. math.floor(val("wd_radius", 32)) .. ":" .. S.mined
                local here = G.pos()
                local list = OE.list
                if key ~= OE.key or not OE.at or (here - OE.at).Magnitude > 3 or os.clock() - (OE.t or 0) > 10 then
                    list = n > 0 and MINE.scan(want, math.floor(val("wd_radius", 32))) or {}
                    OE.list, OE.key, OE.at, OE.t = list, key, here, os.clock()
                end
                for _, o in ipairs(list) do o.d = (Vector3.new(o.x, o.y, o.z) - here).Magnitude end
                local cnt = {}
                for _, o in ipairs(list) do cnt[o.n] = (cnt[o.n] or 0) + 1 end
                local parts = {}
                for k, c in pairs(cnt) do parts[#parts + 1] = G.pretty(k) .. " " .. c end
                table.sort(parts)
                UI.oreTxt = #parts > 0 and table.concat(parts, " · ") or "No picked ores in range"
                for i = 1, math.max(#OE.pool, math.min(#list, 40)) do
                    local o = list[i]
                    local e = OE.pool[i]
                    if o and i <= 40 then
                        if not e then
                            local p = Instance.new("Part")
                            p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.Transparency, p.Size = true, false, false, false, 1, Vector3.new(0.2, 0.2, 0.2)
                            p.Parent = anchors
                            local bb, tl = tag(nil, "", Color3.new(1, 1, 1), 90)
                            bb.Adornee = p
                            local hl = Instance.new("BoxHandleAdornment")
                            hl.AlwaysOnTop, hl.ZIndex, hl.Transparency, hl.Size, hl.Adornee = true, 5, 0.3, Vector3.new(1, 1, 1) * G.BLOCK * 0.4, p
                            hl.Parent = folder
                            e = { p = p, bb = bb, tl = tl, hl = hl }
                            OE.pool[i] = e
                        end
                        local c = COL[o.n] or Color3.fromRGB(230, 230, 230)
                        e.p.Position = Vector3.new(o.x + 0.5, o.y + 0.5, o.z + 0.5) * G.BLOCK
                        e.tl.Text = G.pretty(o.n) .. " " .. math.floor(o.d) .. "b"
                        e.tl.TextColor3, e.hl.Color3 = c, c
                        e.bb.Enabled, e.hl.Visible = true, true
                    elseif e then
                        e.bb.Enabled, e.hl.Visible = false, false
                    end
                end
            else
                for _, e in ipairs(OE.pool) do e.bb.Enabled, e.hl.Visible = false, false end
                UI.oreTxt = nil
            end
            task.wait(1)
        end
    end)
    task.spawn(function()
        while RUNNING do
            local w = 0.5
            if on("wd_mine") and G.inWorld() and not G.dead() and not UI.busy then
                local ok, r = G.job(MINE.step)
                w = ok and tonumber(r) or 1
            elseif on("wd_vac") and G.inWorld() and not G.dead() and not UI.busy and not on("wd_mine") then
                local f = Workspace:FindFirstChild("Drops")
                local p = G.pos()
                local any = false
                if f then for _, d in ipairs(f:GetChildren()) do if d:IsA("BasePart") and (d.Position / G.BLOCK - p).Magnitude <= val("wd_vac_r", 12) then any = true break end end end
                if any then
                    G.job(function() local back = G.pos() MINE.vacuum(val("wd_vac_r", 12)) G.tp(back) end)
                end
                w = 1
            end
            task.wait(w)
        end
    end)
    task.spawn(function()
        local hover = false
        while RUNNING do
            local ok, w = pcall(function()
                local w = 0.2
                local farm = (on("cb_farm") or on("bf_auto")) and not UI.busy
                if farm and G.inWorld() and not G.dead() and (lp:GetAttribute("Health") or 20) <= val("bf_hp", 9) then
                    S.task = __T["Healing in the sky"]
                    local p = G.pos()
                    if not KILL.safe then KILL.safe = Vector3.new(p.X, math.min(p.Y + 25, 120), p.Z) end
                    G.C.canFly = true G.C.flying = true hover = true
                    if (p - KILL.safe).Magnitude > 2 then G.tp(KILL.safe) end
                    return 1
                end
                if farm and KILL.safe and (lp:GetAttribute("Health") or 20) < 18 then return 1 end
                KILL.safe = nil
                if (on("cb_aura") or farm) and G.inWorld() and not G.dead() then
                    local m, d = KILL.near(farm and val("cb_range", 160) or 5.2, on("bf_auto") and KILL.hostile or KILL.want())
                    if m then
                        if on("cb_sword") and not UI.busy then
                            if on("cb_craft") and (not CRAFT.hasSword() or (CRAFT.upgrade() and os.clock() - CRAFT.last > 120)) then G.job(CRAFT.sword) end
                            G.holdWeapon()
                        end
                        if farm then
                            local mp = G.mpos(m)
                            local f = KILL.fail[m] or 0
                            local want = mp + KILL.offs[(math.floor(f / 2) % #KILL.offs) + 1]
                            if (G.pos() - want).Magnitude > 1.5 then
                                G.C.canFly = true G.C.flying = true hover = true
                                G.tp(want)
                                task.wait(0.1)
                            end
                            S.task = __T["Fighting "] .. G.pretty(m:GetAttribute("Kind"))
                        end
                        local gap = 0.66 - (os.clock() - KILL.last)
                        if gap > 0 then task.wait(gap) end
                        KILL.last = os.clock()
                        local h0 = m:GetAttribute("Health")
                        KILL.hit(m)
                        task.wait(0.12)
                        if m:GetAttribute("Health") == h0 and m:GetAttribute("Dead") ~= true then
                            KILL.fail[m] = (KILL.fail[m] or 0) + 1
                            if KILL.fail[m] >= 8 then KILL.skip[m] = os.clock() + 30 KILL.fail[m] = 0 end
                        else KILL.fail[m] = 0 end
                        w = 0.05
                    end
                end
                return w
            end)
            if not ok then LOG("err combat", w) w = 1 end
            if hover and not on("cb_farm") and not on("bf_auto") then hover = false if not G.needFly() then G.C.flying = false G.C.canFly = lp:GetAttribute("Creative") == true end end
            task.wait(w)
        end
    end)
    local ME = {}
    task.spawn(function()
        while RUNNING do
            local ok, err = pcall(function()
            local p = G.pos()
            local alive = {}
            for _, m in ipairs(G.mobs()) do
                if m:IsA("BasePart") and m:GetAttribute("Dead") ~= true then
                    local isJ = m:GetAttribute("Jerry") == true
                    local show = (isJ and on("es_jerry")) or (not isJ and on("es_mobs") and (not on("es_hostile") or KILL.hostile[tostring(m:GetAttribute("Kind"))] or m:GetAttribute("Kind") == "creeper" or m:GetAttribute("Kind") == "enderman"))
                    if show then
                        local d = (G.mpos(m) - p).Magnitude
                        if isJ or d <= 80 then
                            alive[m] = true
                            local e = ME[m]
                            if not e then local bb, tl = tag(nil, "", Color3.new(1, 1, 1), 140) bb.Adornee = m e = { bb = bb, tl = tl } ME[m] = e end
                            local k = tostring(m:GetAttribute("Kind") or "?")
                            local hp = m:GetAttribute("Health")
                            e.tl.Text = (isJ and (tostring(Workspace:GetAttribute("JerryName") or "Jerry")) or G.pretty(k)) .. (hp and ("  " .. hp .. "hp") or "") .. "  " .. math.floor(d) .. "b"
                            e.tl.TextColor3 = isJ and Color3.fromRGB(255, 200, 80) or (G.friendly(m) and Color3.fromRGB(120, 230, 140) or Color3.fromRGB(255, 90, 90))
                            e.bb.Enabled = true
                        end
                    end
                end
            end
            for m, e in pairs(ME) do if not alive[m] then pcall(function() e.bb:Destroy() end) ME[m] = nil end end
            end)
            if not ok then LOG("err mobesp", err) end
            task.wait(0.4)
        end
    end)
    local PE = {}
    task.spawn(function()
        while RUNNING do
            local ok, err = pcall(function()
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl ~= lp then
                    local c = pl.Character
                    local head = c and (c:FindFirstChild("Head") or c:FindFirstChild("HumanoidRootPart") or (c:IsA("BasePart") and c))
                    local e = PE[pl]
                    if on("es_players") and head then
                        if not e then local bb, tl = tag(nil, "", Color3.fromRGB(235, 235, 235), 150) e = { bb = bb, tl = tl } PE[pl] = e end
                        e.bb.Adornee = head
                        e.tl.Text = pl.DisplayName .. "  " .. math.floor((head.Position / G.BLOCK - G.pos()).Magnitude) .. "b"
                        e.bb.Enabled = true
                    elseif e then e.bb.Enabled = false end
                end
            end
            for pl, e in pairs(PE) do if not pl.Parent then pcall(function() e.bb:Destroy() end) PE[pl] = nil end end
            end)
            if not ok then LOG("err playeresp", err) end
            task.wait(0.5)
        end
    end)
end)
onClean(function()
    if G.C then G.C.flying = false G.C.canFly = lp:GetAttribute("Creative") == true end
    if S.pvpWas == false then pcall(function() G.R.Pvp:InvokeServer(false) end) end
end)
section(__T["Visuals"], function()
    local Tab = Window:AddTab(__T["Visuals"], "eye")
    local LB = Tab:AddLeftGroupbox(__T["World"], "sun")
    LB:AddToggle("vs_bright", { Text = __T["Fullbright"], Default = false })
    LB:AddToggle("vs_nofog", { Text = __T["No Fog"], Default = false })
    local EB = Tab:AddRightGroupbox(__T["ESP"], "scan-eye")
    EB:AddToggle("es_mobs", { Text = __T["Mob ESP"], Default = false })
    EB:AddToggle("es_hostile", { Text = __T["Monsters Only"], Default = true })
    EB:AddToggle("es_jerry", { Text = __T["Jerry ESP"], Default = true })
    EB:AddToggle("es_players", { Text = __T["Player ESP"], Default = false })
    EB:AddToggle("es_ptrace", { Text = __T["Player Tracers"], Default = false })
    EB:AddToggle("es_mtrace", { Text = __T["Monster Tracers"], Default = false })
    local LO = {}
    RunService:BindToRenderStep("CWDogLight", Enum.RenderPriority.Last.Value + 10, function()
        if not RUNNING then return end
        if on("vs_bright") then
            if not LO.a then LO.a, LO.o, LO.b = Lighting.Ambient, Lighting.OutdoorAmbient, Lighting.Brightness end
            Lighting.Ambient, Lighting.OutdoorAmbient = Color3.fromRGB(210, 210, 210), Color3.fromRGB(210, 210, 210)
        elseif LO.a then Lighting.Ambient, Lighting.OutdoorAmbient, Lighting.Brightness = LO.a, LO.o, LO.b LO.a = nil end
        if on("vs_nofog") then
            if not LO.f then LO.f, LO.fs = Lighting.FogEnd, Lighting.FogStart end
            Lighting.FogStart, Lighting.FogEnd = 1e5, 1e5 + 1
        elseif LO.f then Lighting.FogEnd, Lighting.FogStart = LO.f, LO.fs LO.f = nil end
    end)
    onClean(function()
        pcall(function() RunService:UnbindFromRenderStep("CWDogLight") end)
        if LO.a then Lighting.Ambient, Lighting.OutdoorAmbient, Lighting.Brightness = LO.a, LO.o, LO.b end
        if LO.f then Lighting.FogEnd, Lighting.FogStart = LO.f, LO.fs end
    end)
    local TR = { pool = {} }
    local okD = pcall(function() return Drawing.new end)
    local function line(i)
        local l = TR.pool[i]
        if not l and okD then
            l = Drawing.new("Line")
            l.Thickness, l.Transparency = 1.5, 0.9
            TR.pool[i] = l
        end
        return l
    end
    onClean(function() for _, l in pairs(TR.pool) do pcall(function() l:Remove() end) end end)
    track(RunService.RenderStepped:Connect(function()
        if not RUNNING or not okD then return end
        local cam = Workspace.CurrentCamera
        local vs = cam.ViewportSize
        local from = Vector2.new(vs.X / 2, vs.Y - 30)
        local n = 0
        local function draw(pos, col)
            local sp, vis = cam:WorldToViewportPoint(pos)
            if not vis then return end
            n += 1
            local l = line(n)
            if l then l.From, l.To, l.Color, l.Visible = from, Vector2.new(sp.X, sp.Y), col, true end
        end
        if on("es_ptrace") then
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl ~= lp then
                    local c = pl.Character
                    local part = c and (c:IsA("BasePart") and c or c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Head"))
                    if part then draw(part.Position, Color3.fromRGB(90, 200, 255)) end
                end
            end
        end
        if on("es_mtrace") then
            local p = G.pos()
            for _, m in ipairs(G.mobs()) do
                if m:IsA("BasePart") and m:GetAttribute("Dead") ~= true and (KILL.hostile[tostring(m:GetAttribute("Kind"))] or m:GetAttribute("Jerry") == true and m:GetAttribute("Feral") == true) and (G.mpos(m) - p).Magnitude < 80 then
                    draw(m.Position, Color3.fromRGB(255, 80, 80))
                end
            end
        end
        for i = n + 1, #TR.pool do TR.pool[i].Visible = false end
    end))
end)
task.spawn(function()
    while RUNNING do
        pcall(function()
            S.bones0 = S.bones0 or G.wallet()
            local mode = G.mode()
            local ch, day = Workspace:GetAttribute("Chapter"), Workspace:GetAttribute("StoryDay") or Workspace:GetAttribute("Day")
            local night = Workspace:GetAttribute("Night")
            local line = mode
            if mode == "Story" then line = line .. (ch and (" · Chapter " .. ch) or "") .. (day and (" · Day " .. day) or "")
            elseif mode == "Survival" then line = line .. (night and (" · Night " .. night) or "") .. (Workspace:GetAttribute("Phase") and (" · " .. tostring(Workspace:GetAttribute("Phase"))) or "") end
            setText(UI.s0, line)
            setText(UI.s1, string.format(__T["Health %s · Food %s"], tostring(lp:GetAttribute("Health") or "-"), tostring(lp:GetAttribute("Food") or "-")))
            local mins = math.max(1, (os.clock() - S.t0) / 60)
            local gain = G.wallet() - S.bones0
            setText(UI.s2, string.format(__T["Bones %d (+%d, %d/h)"], G.wallet(), gain, math.floor(gain / mins * 60)) .. (UI.earnTxt and ("\n" .. UI.earnTxt) or ""))
            local obj = Workspace:GetAttribute("QuestLabel") or Workspace:GetAttribute("Objective")
            setText(UI.s3, (obj and obj ~= "") and (__T["Goal: "] .. tostring(obj)) or __T["Goal: -"])
            local m = os.clock() - S.msgAt < 8 and S.msg or ""
            setText(UI.task, "<b>" .. tostring(S.task) .. "</b>" .. (m ~= "" and ("\n" .. m) or ""))
            local q = Workspace:GetAttribute("QuestTarget")
            setText(UI.obj, typeof(q) == "Vector3" and string.format(__T["Objective %d blocks away"], math.floor((q - G.pos()).Magnitude)) or __T["No objective marker"])
            local j = G.jerry()
            local jh, ja = Workspace:GetAttribute("JerryHunger"), Workspace:GetAttribute("JerryAffection")
            setText(UI.jr, j and string.format(__T["Hunger %s · Love %s · %s\nFood in bag: %d · Fed %d"], tostring(jh or "-"), tostring(ja or "-"), tostring(j:GetAttribute("Mood") or (j:GetAttribute("Tame") and __T["tame"] or __T["wild"])), G.foodCount(), S.fed) or __T["Jerry is not here"])
            setText(UI.rw, Workspace:FindFirstChild("LooseBones") and string.format(__T["Loose bones picked: %d"], S.bonesPicked or 0) or __T["Loose bones: Survival only"])
            setText(UI.ore, UI.oreTxt or (on("wd_mine") and "" or __T["Turn on Ore ESP to count ores"]))
            local e = S.earn
            setText(UI.cb, string.format(__T["Kills %d · Bones from kills %d"], S.kills, e.Kills or 0))
            local parts = {}
            for _, k in ipairs({ "Kills", "Loose", "Jerry", "Alive", "Other" }) do if (e[k] or 0) > 0 then parts[#parts + 1] = k .. " " .. e[k] end end
            UI.earnTxt = #parts > 0 and table.concat(parts, " · ") or nil
            setText(UI.pl, string.format(__T["Mined %d · Picked up %d"], S.mined, S.picked))
            setText(UI.bf, G.MODE.isSurvival and (on("bf_auto") and ("<b>" .. tostring(S.task) .. "</b>") or __T["Off"]) or __T["Survival only. Join from the lobby."])
            if not on("wd_mine") and not on("cb_farm") and not on("bf_auto") and S.task ~= "Idle" and not UI.busy then S.task = "Idle" end
        end)
        task.wait(0.5)
    end
end)
section(__T["Streamer"], function()
    local Tab = Window:AddTab(__T["Streamer"], "eye")
    local ST = { HideMe = false, FakeName = "Player", HideOthers = false, HideAvatars = false, HidePlayerList = false, HideChat = false }
    ST.conns, ST.objConns, ST.orig, ST.written, ST.alias = {}, setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    ST.aliasN, ST.rev = 0, {}
    local rules, ids = {}, {}
    local function aliasFor(plr)
        if plr == lp then return (ST.FakeName ~= "" and ST.FakeName) or "Player" end
        if not ST.alias[plr] then ST.aliasN = ST.aliasN + 1 ST.alias[plr] = "Player " .. ST.aliasN end
        return ST.alias[plr]
    end
    local function active() return ST.HideMe or ST.HideOthers or ST.HideAvatars end
    local function esc(s) return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0")) end
    local ZW = utf8.char(0x200B)
    local function unfix(t)
        if not t:find(ZW, 1, true) then return t end
        local keys = {} for k in pairs(ST.rev) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return #a > #b end)
        for _, k in ipairs(keys) do if t:find(k, 1, true) then t = t:gsub(esc(k), (ST.rev[k]:gsub("%%", "%%%%"))) end end
        return (t:gsub(ZW, ""))
    end
    local function rebuild()
        rules, ids = {}, {}
        local seen = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            local mine = plr == lp
            if (mine and ST.HideMe) or (not mine and ST.HideOthers) then
                local a = aliasFor(plr)
                for i, n in ipairs({ plr.DisplayName, plr.Name }) do
                    if type(n) == "string" and #n >= 3 and not seen[n] then
                        seen[n] = true
                        local rep = a .. ZW .. (i == 2 and ZW or "")
                        rules[#rules + 1] = { pat = "%f[%w_]" .. esc(n) .. "%f[^%w_]", plain = n, rep = rep }
                        ST.rev[rep] = n
                    end
                end
            end
            if ST.HideAvatars and (mine or ST.HideOthers) then ids[#ids + 1] = tostring(plr.UserId) end
        end
        table.sort(rules, function(a, b) return #a.plain > #b.plain end)
    end
    local function fixText(t) local o = t for _, r in ipairs(rules) do if o:find(r.plain, 1, true) then o = o:gsub(r.pat, (r.rep:gsub("%%", "%%%%"))) end end return o end
    local function fixImg(img) for _, id in ipairs(ids) do if img:find("=" .. id, 1, true) then return "" end end return img end
    local function propOf(d) if d:IsA("TextLabel") or d:IsA("TextButton") then return "Text" elseif d:IsA("ImageLabel") or d:IsA("ImageButton") then return "Image" end end
    local function process(d)
        local p = propOf(d) if not p then return end
        local cur = d[p]
        if ST.written[d] ~= nil and cur == ST.written[d] then return end
        local fixed = p == "Text" and fixText(cur) or fixImg(cur)
        if fixed ~= cur then ST.orig[d], ST.written[d] = cur, fixed d[p] = fixed else ST.orig[d], ST.written[d] = nil, nil end
    end
    local function watch(d) if ST.objConns[d] then return end local p = propOf(d) if not p then return end ST.objConns[d] = d:GetPropertyChangedSignal(p):Connect(function() if active() then pcall(process, d) end end) pcall(process, d) end
    local function walk(inst, d) if d > 60 then return end local ok, k = pcall(inst.GetChildren, inst) if not ok then return end for _, c in ipairs(k) do pcall(watch, c) walk(c, d + 1) end end
    local function setHum(plr) local h = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then local hide = (plr == lp and ST.HideMe) or (plr ~= lp and ST.HideOthers) pcall(function() h.DisplayName = hide and aliasFor(plr) or plr.DisplayName end) end end
    local function startWatch()
        if ST.watching then return end
        ST.watching = true
        local roots = { lp:WaitForChild("PlayerGui") }
        pcall(function() roots[#roots + 1] = game:GetService("CoreGui") end)
        pcall(function() local h = gethui and gethui() if typeof(h) == "Instance" then roots[#roots + 1] = h end end)
        pcall(function() roots[#roots + 1] = Workspace end)
        for i, rt in ipairs(roots) do walk(rt, 0) ST.conns["a" .. i] = rt.DescendantAdded:Connect(function(d) if propOf(d) then task.defer(function() if active() and d.Parent then watch(d) end end) end end) end
    end
    local function restoreAll()
        for d in pairs(ST.objConns) do pcall(function() if propOf(d) == "Text" then local u = unfix(d.Text) if u ~= d.Text then d.Text = u end elseif propOf(d) == "Image" and ST.orig[d] then d.Image = ST.orig[d] end end) end
        ST.written, ST.orig = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    end
    local function refresh()
        rebuild()
        for _, p in ipairs(Players:GetPlayers()) do setHum(p) end
        restoreAll()
        if active() then if ST.watching then for d in pairs(ST.objConns) do pcall(process, d) end else startWatch() end end
    end
    local function applyCore()
        pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, not ST.HidePlayerList) end)
        if ST.HideChat then pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, false) end) pcall(function() TextChatService.ChatWindowConfiguration.Enabled = false end)
        else pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, true) end) pcall(function() TextChatService.ChatWindowConfiguration.Enabled = true end) end
    end
    track(Players.PlayerAdded:Connect(function() if active() then refresh() end end))
    local B = Tab:AddLeftGroupbox(__T["Hide Identity"], "user")
    B:AddToggle("st_me", { Text = __T["Hide My Name"], Default = false, Callback = function(v) ST.HideMe = v refresh() end })
    B:AddInput("st_name", { Text = __T["Fake Name"], Default = "Player", Finished = true, Callback = function(v) v = tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "") ST.FakeName = (v ~= "" and v:sub(1, 20)) or "Player" refresh() end })
    B:AddToggle("st_others", { Text = __T["Hide Other Names"], Default = false, Callback = function(v) ST.HideOthers = v refresh() end })
    B:AddToggle("st_av", { Text = __T["Hide Avatars"], Default = false, Callback = function(v) ST.HideAvatars = v refresh() end })
    local B2 = Tab:AddRightGroupbox(__T["Hide Roblox UI"], "monitor")
    B2:AddToggle("st_list", { Text = __T["Hide Player List"], Default = false, Callback = function(v) ST.HidePlayerList = v applyCore() end })
    B2:AddToggle("st_chat", { Text = __T["Hide Chat"], Default = false, Callback = function(v) ST.HideChat = v applyCore() end })
    onClean(function() ST.HideMe, ST.HideOthers, ST.HideAvatars, ST.HidePlayerList, ST.HideChat = false, false, false, false, false pcall(refresh) pcall(applyCore) for _, c in pairs(ST.conns) do pcall(function() c:Disconnect() end) end end)
end)
section(__T["Settings"], function()
    local Tab = Window:AddTab(__T["Settings"], "settings")
    local Menu = Tab:AddLeftGroupbox(__T["Menu"], "menu")
    Menu:AddLabel(__T["Menu Key"]):AddKeyPicker("MenuKeybind", { Default = "RightShift", NoUI = true, Text = __T["Menu Key"] })
    Library.ToggleKeybind = Opt.MenuKeybind
    Menu:AddDropdown("ui_scale", { Text = __T["UI Scale"], Values = { "60%", "75%", "90%", "100%", "110%", "125%" }, Default = Library.IsMobile and "75%" or "100%", Callback = function(v) pcall(function() Library:SetDPIScale(tonumber(tostring(v):match("%d+")) or 100) end) end })
    if Library.IsMobile then pcall(function() Library:SetDPIScale(75) end) end
    Menu:AddButton({ Text = __T["Unload"], Func = function() pcall(_G.__CW_DOG_CLEAN) end })
    local SV = Tab:AddLeftGroupbox(__T["Server"], "server")
    SV:AddButton({ Text = __T["Rejoin"], Func = function() pcall(function() TeleportService:Teleport(game.PlaceId, lp) end) end })
    SaveManager:SetLibrary(Library)
    ThemeManager:SetLibrary(Library)
    SaveManager:IgnoreThemeSettings()
    SaveManager:SetIgnoreIndexes({ "MenuKeybind", "FeedbackType", "FeedbackMsg" })
    ThemeManager:SetFolder("COMBO_WICK_DOG")
    SaveManager:SetFolder("COMBO_WICK_DOG")
    ThemeManager:ApplyToTab(Tab)
    pcall(function()
        if not (isfile and isfile("COMBO_WICK_DOG/themes/default.txt")) then ThemeManager:ApplyTheme("Tokyo Night") end
    end)
    SaveManager:BuildConfigSection(Tab)
end)
onClean(function() pcall(function() Library:Unload() end) end)
onClean(function() pcall(function() RunService:Set3dRenderingEnabled(true) end) end)
pcall(function()
    if isfile and isfile("COMBO_WICK_DOG/settings/auto.json") then SaveManager:Load("auto") else SaveManager:LoadAutoloadConfig() end
end)
do
    local pending = false
    local function queue()
        if pending or not RUNNING then return end
        pending = true
        task.delay(1.5, function() pending = false; if RUNNING then pcall(function() SaveManager:Save("auto") end) end end)
    end
    local function skip(k) k = tostring(k); return k == "MenuKeybind" or k:find("^ThemeManager") or k:find("^SaveManager") or k:find("Color") or k == "FeedbackMsg" or k == "FeedbackType" end
    task.delay(2, function()
        for k, t in pairs(Toggles) do if not skip(k) then pcall(function() local prev = t.Changed t:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
        for k, o in pairs(Opt) do if not skip(k) then pcall(function() local prev = o.Changed o:OnChanged(function(...) if prev then pcall(prev, ...) end queue() end) end) end end
    end)
end
task.delay(1, function()
    pcall(function()
        local m = Library.ScreenGui and Library.ScreenGui:FindFirstChild("Main")
        if m then m.AnchorPoint = Vector2.zero m.Position = UDim2.new(0.5, -math.floor(m.AbsoluteSize.X / 2), 0.5, -math.floor(m.AbsoluteSize.Y / 2)) end
    end)
end)
notify(__T["Loaded"])

